with anchor as (select max(as_of) a from index_snapshot where index_id='NIFTY200'),
docs as (select * from index_release_document d where parser_version=(select max(parser_version) from index_release_document x where x.doc_id=d.doc_id)),
snaps as (select * from index_monthly_snapshot s where parser_version=(select max(parser_version) from index_monthly_snapshot y where y.index_name=s.index_name and y.as_of=s.as_of))
select 'anchor', 1, (select a::text from anchor)
union all select 'index_snapshot@anchor', count(*), md5(coalesce(string_agg(x::text,'|' order by x::text),'')) from index_snapshot x where as_of=(select a from anchor)
union all select 'release_document(latest parser)', count(*), md5(coalesce(string_agg(t,'|' order by t),'')) from (select (doc_id,parser_version,announced,source_url,source_hash,kind,sections,notes,classification,classification_reason,extracted_text)::text t from docs) q
union all select 'release_row(latest parser)', count(*), md5(coalesce(string_agg(t,'|' order by t),'')) from (select (r.doc_id,r.parser_version,r.page,r.section_no,r.section_name,r.component,r.action,r.symbol,r.company,r.effective_from,r.related_symbol,r.raw_text,r.instrument_id,r.mapping_status,r.review_status)::text t from index_release_row r join docs d using (doc_id,parser_version)) q
union all select 'monthly_snapshot(latest parser)', count(*), md5(coalesce(string_agg(t,'|' order by t),'')) from (select (index_name,component,as_of,zip_hash,pdf_name,pdf_hash,parser_version,problems)::text t from snaps) q
union all select 'monthly_constituent(latest parser)', count(*), md5(coalesce(string_agg(t,'|' order by t),'')) from (select (s.index_name,s.as_of,s.parser_version,k.symbol,k.name,k.industry,k.price,k.index_mcap,k.weight,k.page,k.instrument_id,k.mapping_status)::text t from index_monthly_constituent k join snaps s using (snapshot_id)) q
union all select 'revocation', count(*), md5(coalesce(string_agg(t,'|' order by t),'')) from (select (doc_id,component,symbol,kind,effective_from,authority_doc,authority_date,authority_quote,method,verification)::text t from index_release_revocation) q
union all select 'placeholder_replacement', count(*), md5(coalesce(string_agg(t,'|' order by t),'')) from (select (evidence_doc,placeholder,symbol,listed_on,quote,method,verification)::text t from index_placeholder_replacement) q
union all select 'instrument+alias+relationship', (select count(*) from instrument)+(select count(*) from instrument_alias)+(select count(*) from corporate_action_relationship), md5((select string_agg(x::text,'|' order by x::text) from instrument x)||(select string_agg(x::text,'|' order by x::text) from instrument_alias x)||(select string_agg(x::text,'|' order by x::text) from corporate_action_relationship x))
order by 1;
